# -*- coding: utf-8 -*-
# Correcoes do revisor nativo (aplicadas). Sobrescrevem p1..p6.
R = "[rev. nativo]"
DE = {
"B008": ("Und viele Gläubige wandten sich an ihn, wenn sie spürten, dass ein unsichtbarer Schatten auf ihrem Leben lastete. Doch eines erklärt kaum jemand.", R),
"B015": ("Darum ist diese Übertragung nicht zufällig zu Ihnen gekommen. Heute, hier, werden Sie verstehen, wie ein heiliges Benediktusgebet, sieben Minuten lang geführt, Schutz herabrufen, Wege öffnen und Ihr geistliches Leben wieder mit dem Segen verbinden kann,", R),
"B019": ("Atmen Sie also tief durch, lassen Sie alle Ablenkungen hinter sich und bleiben Sie bei mir bis zum Ende. Denn jetzt werden Sie verstehen, warum das Gebet des heiligen Benedikt über Jahrhunderte als eines der stärksten geistlichen Werkzeuge bewahrt wurde – für Schutz und für neue Wege.", R),
"B034": ("Brüder und Schwestern, in den nächsten 57 Sekunden erhalten die Auserwählten Gottes Zugang zum heiligen Benediktusgebet – einem Gebet, das finanzielle Wunder bewirkt, Krankheiten heilt, Ehen wiederherstellt,", R),
"B035": ("Frieden in die Familie bringt, Wege öffnet, Häuser befreit, Wohlstand anzieht und Schicksale wendet.", R),
"B037": ("Meine Lieben zu Hause, schreiben Sie jetzt Ihre Anliegen in den Chat. Ich lese einige Nachrichten vor. Eine Mutter aus Dortmund bittet um unser Gebet: Sie ist hoch verschuldet und kann vor lauter Geldsorgen nicht mehr schlafen.", R),
"B038": ("Ein Familienvater aus Berlin bittet um Segen, damit er Arbeit findet. Er ist seit Monaten mit der Miete im Rückstand, und seine Kinder leiden Not.", R),
"B040": ("Sie alle werden heute gesegnet, denn in wenigen Minuten erhalten Sie Zugang zum heiligen Benediktusgebet.", R),
"B048": ("Ehrlich gesagt hatte ich anfangs Zweifel. Aber nach und nach änderte sich etwas: Ich bekam mehr Ordnung ins Leben, verkaufte Produkte von zu Hause aus, regelte meine Schulden und war beim Thema Geld endlich wieder ruhig.", R),
"B049": ("Heute habe ich Stabilität. Aber das Schönste war: Mein Mann hat sich verändert, zu Gott zurückgefunden, betet wieder mit mir – wir gehen unseren Weg wieder gemeinsam.", R),
"B050": ("Padre Juan, von Herzen Dank. Dieses Gebet hat unsere Familie verändert.", R),
"B065": ("Zuallererst sollen Sie wissen: Ich habe unseren himmlischen Vater inständig angefleht, genau die Menschen hierherzuführen, die dringend Segen und Wunder brauchen.", R),
"B066": ("Wenn Sie also jetzt bei mir sind, hat das einen Grund: Gott schenkt Ihnen die Gelegenheit zu verstehen, wie Sie die Kraft freisetzen, Wunder in Ihrem Leben zu erfahren.", R),
"B068": ("Darum bereiten Sie Ihr Herz im Glauben vor, denn Sie werden gleich den Segen dieses kraftvollen Benediktusgebets empfangen.", R),
"B074": ("Diese Offenbarung kann Ihr Leben mit Gott in wenigen Wochen vollkommen verändern. Was tun, wenn Gebete nicht erhört werden?", R),
"B075": ("Eine Nonne aus einem Klausurkloster, die 67 Jahre ihres Lebens dem Gebet geweiht hat, zeigt Ihnen den feinen Fehler, den neunundneunzig Prozent der Gläubigen beim Beten machen – und der verhindert, dass Gott sie erhört.", R),
"B076": ("Das Geheimnis, das mir ein 93-jähriger Bischof über die Freimaurer anvertraute – streng unter Verschluss gehalten –, kann Ihren Geist neu programmieren und in sieben Tagen Reichtum, Gesundheit und Glück bringen.", R),
"B078": ("Selbst dem reichsten Mann der Welt wurde verwehrt, es zu kaufen. Heute ist ein Tag, den Sie nie vergessen werden. Wahrscheinlich kenne ich Sie nicht, aber eines weiß ich: Vielleicht leiden Sie, tragen einen tiefen Schmerz wegen etwas, das Ihnen ausweglos erscheint – Schulden, die nur wachsen, eine unerträgliche Arbeit,", R),
"B079": ("eine Krankheit oder Probleme in der Liebe. Und all das verursacht schreckliche Angst, seelischen Schmerz, Streit in der Familie, den Schmerz der Einsamkeit. Nichts davon ist leicht.", R),
"B081": ("Hören Sie genau zu, denn Sie erhalten nicht nur Zugang zum mächtigsten Wohlstandsgebet der Welt, sondern erfahren auch die drei Geheimnisse, die der Vatikan unter sieben Siegeln hütet – Geheimnisse, die mir persönlich offenbart wurden, in den frühen Morgenstunden des dreiundzwanzigsten März 2025.", R + " Data por extenso para a TTS."),
"B088": ("Und es spielt auch keine Rolle, welcher Religion Sie angehören. Alles begann am vierundzwanzigsten November 2024. Es war ein kalter, trüber Sonntag.", R),
"B092": ("Es war der größte Schmerz meines Lebens. Ich sah die Verzweiflung in den Augen meines Bruders und die Ungewissheit über die Zukunft unserer Mutter.", R),
"B093": ("Sofort suchten wir nach anderen Möglichkeiten und stießen auf die Cleveland Clinic – eine Spezialklinik mit einer Behandlung, die sich noch in der Erprobung befand und schon für den Beginn rund neunzigtausend Euro kostete.", R + " 90.000 € por extenso para a TTS."),
"B097": ("Am nächsten Morgen, als ich es am wenigsten erwartete, erhielt ich eine Nachricht, die mich verstummen ließ: Unsere Pfarrei war vom Bischof ausgewählt worden, an einer Pilgerreise nach Italien teilzunehmen – zum Kloster des heiligen Benedikt.", R),
"B099": ("Als ich im Kloster in Italien ankam, empfing mich Seine Exzellenz Bischof Felipe Santoro. Dieser Diener Gottes kleidete sich demütig und schlicht.", R),
"B103": ("Es war altes Italienisch, ich verstand es nicht, aber die Worte schwangen in einer anderen Frequenz. Mein Geist wurde in ein wunderschönes grünes Tal getragen: Die Vögel sangen, die Blumen blühten, und die Sonne schien.", R),
"B113": ("Drei Tage später geschah etwas Außergewöhnliches: Es kam eine anonyme Spende über fünfunddreißigtausend Euro.“", R + " 35.000 € por extenso."),
"B117": ("Der Satan weiß das. Darum benutzt er Unruhe, Angst und Sorgen, um diese Antenne zu blockieren.", R),
"B118": ("Der Bischof offenbarte mir, dass das Benediktusgebet genau die Klangfrequenz ist, die die Blockade der Zirbeldrüse löst – damit Sie sich mit Ihrem Schutzengel verbinden und das Wunder empfangen, das Sie brauchen.", R),
"B120": ("Doch bei neunundneunzig Prozent der Menschen ist diese Antenne abgeschaltet. Und es gibt einen ganz einfachen Weg herauszufinden, ob Ihre Antenne der Wunder aktiv ist oder nicht.", R),
"B126": ("Und jetzt fragen Sie sich vielleicht, wie man diese Frequenz wiederfindet. Genau hier kommt das heilige Benediktusgebet ins Spiel: Es besitzt eine vollkommene Kombination aus Worten und Klangfrequenzen, die unsere Antenne der Wunder wieder aktiviert und uns erneut mit unserem Schutzengel verbindet.", R),
"B130": ("Sie werden nie erreichen, was Gott für Sie geplant hat. Die Moderne hat uns das genommen. Aber wir sind kurz davor, diese Kraft zurückzugewinnen. Denn wenn Sie Zugang zu diesem heiligen Gebet erhalten, wird Ihre Antenne der Wunder in ihren ursprünglichen Zustand zurückversetzt, die Verbindung zu Ihrem Schutzengel wird hergestellt,", R),
"B131": ("und Sie können seine Gaben und seinen göttlichen Segen empfangen. Mit Gottes Erlaubnis kann ich Ihnen sagen: Als Priester habe ich schon viel Göttliches erlebt – aber nichts kommt den Geheimnissen dieses heiligen Benediktusgebets gleich.", R),
"B138": ("zusammen mit unserer Mutter. Und drei Tage später schien es, als hätten wir endlich die Verbindung zu unserem Schutzengel gefunden. Wie durch ein Wunder ging es meiner Mutter deutlich besser, und sie durfte nach Hause. Die Ärzte warnten jedoch, ihr blieben weniger als zwei Monate zu leben.", R),
"B140": ("Das Gehalt: neunundzwanzigtausendsiebenhundert Euro im Jahr, plus Provisionen. Mein Gott – war das alles nur Zufall oder die Frucht des heiligen Benediktusgebets?", R),
"B142": ("Obwohl ich Priester bin, war ich von dieser Nachricht zutiefst bewegt. Ich weinte stundenlang vor Rührung und dankte Gott, dem heiligen Benedikt und unserem Schutzengel. Und dann kam das Beste von allem.", R),
"B149": ("Als ich all das sah, wollte ich unbedingt einige Originalfassungen dieses Gebets in meine Pfarrei bringen. Und am dreiundzwanzigsten März 2025 bekam ich ein geheimes Treffen mit dem Bischof, der in Rom über die alten Archive des Vatikans wacht – damals schon schwer krank", R),
"B150": ("und heute in Frieden beim himmlischen Vater ruht. Während des Treffens siegte mein Glaube, denn was Gott geschrieben hat, kann niemand ändern.", R),
"B153": ("Meine Hände begannen zu zittern, ich spürte eine sehr starke Kraft, die davon ausging. So etwas hatte ich noch nie erlebt. Aber ich musste mich verpflichten, einige Regeln einzuhalten: die Originalfassung auf Italienisch zu bewahren, im alten Dialekt, mit den engelsgleichen Klangfrequenzen im Hintergrund,", R),
"B154": ("es mit dem offiziellen Echtheitssiegel zu versehen, um Nachahmungen zu verhindern, und alle, die es erhalten, anzuleiten, es mit Weisheit zu gebrauchen.", R),
"B155": ("Jetzt frage ich Sie: Glauben Sie, dass Gott Ihr Leben verändern und Ihnen Fülle und Wohlstand schenken kann? Wenn ja, möchte ich eine Abmachung mit Ihnen treffen.", R),
"B156": ("An die wenigen Auserwählten, die heute live in dieser Messe bei mir sind: Wenn Sie Gott sieben Minuten am Tag schenken, mit aufrichtigem Glauben im Herzen – ich habe gesehen, wie Gott selbst in wenigen Tagen Wunder wirkt.", R),
"B164": ("Wenn Sie also hier sind, möchte ich Ihnen das heilige Benediktusgebet anvertrauen, das die Eliten totgeschwiegen haben – allen, die im Herzen spüren, dass sie es heute brauchen.", R),
"B171": ("Deshalb gibt es heute eine einfache Möglichkeit, diesen Weg weiterzugehen: Sie können Ihren Zugang heute mit einem Beitrag von nur 37 Euro bestätigen.", R),
"B172": ("Das ist kein Preis, sondern ein Versprechen – an Sie selbst, an Ihren Frieden und an diesen Neuanfang. Und Sie gehen kein Risiko ein: Sie haben 90 Tage Garantie.", R),
"B179": ("Und zum Schluss erhalten Sie ein Überraschungsgeschenk. Darüber darf ich nicht viel mehr sagen, denn es ist nicht öffentlich erhältlich und nur für die Menschen bestimmt, die vertrauen und Zugang zum heiligen Benediktusgebet erhalten.", R),
"B181": ("Das sind keine bloßen Materialien. Es sind Werkzeuge des Glaubens, die Sie in diesem Neuanfang tragen, führen und stärken sollen.", R),
"B200": ("„Kostet der Zugang zum Gebet monatlich etwas?“ Nein. Sie zahlen einmalig 37 Euro und erhalten Zugang zum heiligen Benediktusgebet und zu allen Materialien dieses Angebots.", R),
"B211": ("„Mein Mann hat gesehen, wie ich mich verändert habe, und möchte jetzt auch beten. Kann er das Gebet mit mir zusammen hören?“", R),
"B220": ("Kann ich das Benediktusgebet trotzdem nutzen?“ Ja, Klaus. Sie müssen keiner bestimmten Kirche angehören und auch keinen vollkommenen Glauben haben, um zu beginnen.", R),
"B223": ("Dafür müssen Sie sich nicht unwürdig fühlen. Sie müssen nur mit Ehrfurcht zuhören, Ihr Herz offen halten und bereit sein, sich ein paar Minuten zu nehmen, um wieder in Verbindung zu kommen. Der Glaube ist nicht immer vollständig da, bevor man den ersten Schritt geht.", R),
"B229": ("Christian Krämer fragt: „Ich bin bereit. Wie fange ich an?“ Ganz einfach.", R),
"B234": ("Der Button befindet sich direkt hier unten. Klicken Sie jetzt, bestätigen Sie Ihren Zugang und beginnen Sie diesen Weg mit dem heiligen Benediktusgebet.", R),
}
